const dbState = $json;
const batch = $('Format Batch Metrics').first().json;

return [{
  json: {
    status: 'SUCCESS',
    batch_summary: batch,
    database_verification: {
      total_companies: Number(dbState.total_companies),
      outreach_ready: Number(dbState.outreach_ready),
      total_contacts: Number(dbState.total_contacts),
      staged_drafts: Number(dbState.staged_drafts),
      checkpoint_items_processed: Number(dbState.checkpoint_items_processed)
    },
    timestamp: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'SKIPPED',
    reason: 'Job already in progress — overlapping execution prevented',
    checkpoint: $('Check Status & Overlap Lock').first().json.checkpoint,
    timestamp: new Date().toISOString()
  }
}];
